        'AUTO-PILOT READY' => array('tr'=>'OTOMATİK PİLOT HAZIR','de'=>'AUTO-PILOT BEREIT','fr'=>'PILOTE AUTOMATIQUE PRÊT','es'=>'PILOTO AUTOMÁTICO LISTO','pt'=>'PILOTO AUTOMÁTICO PRONTO','it'=>'PILOTA AUTOMATICO PRONTO','nl'=>'AUTO-PILOOT GEREED','ru'=>'АВТОПИЛОТ ГОТОВ','zh'=>'自动驾驶就绪','ja'=>'オートパイロット準備完了','ko'=>'자동 결제 준비 완료','ar'=>'الطيار الآلي جاهز','hi'=>'ऑटो-पायलट तैयार','pl'=>'AUTOPILOT GOTOWY'),
        'Auto-Pilot Device Mismatch!' => array('tr'=>'Otomatik Pilot Cihaz Uyumsuzluğu!','de'=>'Auto-Pilot Gerätekonflikt!','fr'=>'Incompatibilité d\'appareil Auto-Pilote!','es'=>'¡Incompatibilidad de dispositivo Auto-Piloto!','pt'=>'Incompatibilidade de dispositivo Auto-Piloto!','it'=>'Disallineamento dispositivo Auto-Pilota!','nl'=>'Auto-Piloot apparaat mismatch!','ru'=>'Несоответствие устройства Автопилота!','zh'=>'自动驾驶设备不匹配！','ja'=>'オートパイロット デバイス不一致！','ko'=>'자동 결제 장치 불일치!','ar'=>'عدم تطابق جهاز الطيار الآلي!','hi'=>'ऑटो-पायलट डिवाइस बेमेल!','pl'=>'Niezgodność urządzenia Autopilota!'),
        'SERVICE & COMMISSION POLICY:' => array('tr'=>'HİZMET VE KOMİSYON POLİTİKASI:','de'=>'SERVICE- & PROVISIONSRICHTLINIE:','fr'=>'POLITIQUE DE SERVICE & COMMISSION:','es'=>'POLÍTICA DE SERVICIO Y COMISIÓN:','pt'=>'POLÍTICA DE SERVIÇO E COMISSÃO:','it'=>'POLITICA SERVIZIO E COMMISSIONE:','nl'=>'SERVICE- & COMMISSIEBELEID:','ru'=>'ПОЛИТИКА ОБСЛУЖИВАНИЯ И КОМИССИЙ:','zh'=>'服务与佣金政策：','ja'=>'サービス＆手数料ポリシー：','ko'=>'서비스 및 수수료 정책:','ar'=>'سياسة الخدمة والعمولة:','hi'=>'सेवा और कमीशन नीति:','pl'=>'POLITYKA USŁUG I PROWIZJI:'),
        'Backup these mnemonic words to a safe place NOW!' => array('tr'=>'Anımsatıcı kelimeleri ŞİMDİ güvenli bir yere yedekleyin!','de'=>'Sichern Sie die mnemonischen Wörter JETZT an einem sicheren Ort!','fr'=>'Sauvegardez ces mots mnémoniques dans un endroit sûr MAINTENANT!','es'=>'¡Respalde estas palabras mnemónicas en un lugar seguro AHORA!','pt'=>'Faça backup das palavras mnemônicas em um local seguro AGORA!','it'=>'Effettua il backup delle parole mnemoniche in un luogo sicuro ORA!','nl'=>'Maak NU een back-up van de mnemonische woorden!','ru'=>'Сохраните мнемонические слова в безопасном месте СЕЙЧАС!','zh'=>'立即将助记词备份到安全的地方！','ja'=>'ニーモニックワードを今すぐ安全な場所にバックアップしてください！','ko'=>'니모닉 단어를 지금 안전한 곳에 백업하세요!','ar'=>'قم بنسخ الكلمات المفتاحية احتياطيًا في مكان آمن الآن!','hi'=>'स्मरणीय शब्दों का अभी सुरक्षित स्थान पर बैकअप लें!','pl'=>'Wykonaj kopię zapasową słów mnemonicznych TERAZ!'),
        'NEVER share them with anyone' => array('tr'=>'Bunları KİMSEYLE paylaşmayın','de'=>'Teilen Sie sie NIEMALS mit anderen','fr'=>'Ne les partagez JAMAIS avec quiconque','es'=>'NUNCA los comparta con nadie','pt'=>'NUNCA os compartilhe com ninguém','it'=>'NON condividerle MAI con nessuno','nl'=>'Deel ze NOOIT met iemand','ru'=>'НИКОГДА не делитесь ими','zh'=>'绝对不要与任何人分享','ja'=>'絶対に他人と共有しないでください','ko'=>'절대 다른 사람과 공유하지 마세요','ar'=>'لا تشاركها مع أي شخص أبدًا','hi'=>'इन्हें कभी किसी के साथ साझा न करें','pl'=>'NIGDY ich nikomu nie udostępniaj'),
        'Once ACTIVATE MODULE is clicked, your keys are encrypted and stored ONLY in THIS browser\'s LocalStorage!' => array('tr'=>'MODÜLÜ ETKİNLEŞTİR tıklandığında anahtarlarınız şifrelenir ve YALNIZCA BU tarayıcının LocalStorage\'ında saklanır!','de'=>'Nach Klick auf MODUL AKTIVIEREN werden Ihre Schlüssel verschlüsselt und NUR im LocalStorage DIESES Browsers gespeichert!','fr'=>'Une fois ACTIVER LE MODULE cliqué, vos clés sont chiffrées et stockées UNIQUEMENT dans le LocalStorage de CE navigateur!','es'=>'Al hacer clic en ACTIVAR MÓDULO, sus claves se cifran y almacenan SOLO en el LocalStorage de ESTE navegador!','pt'=>'Ao clicar em ATIVAR MÓDULO, suas chaves são criptografadas e armazenadas APENAS no LocalStorage DESTE navegador!','it'=>'Cliccando ATTIVA MODULO, le chiavi vengono crittografate e memorizzate SOLO nel LocalStorage di QUESTO browser!','nl'=>'Na klikken op MODULE ACTIVEREN worden uw sleutels versleuteld en ALLEEN opgeslagen in de LocalStorage van DEZE browser!','ru'=>'После нажатия АКТИВИРОВАТЬ МОДУЛЬ ваши ключи шифруются и сохраняются ТОЛЬКО в LocalStorage ЭТОГО браузера!','zh'=>'点击激活模块后，您的密钥将被加密并仅存储在此浏览器的LocalStorage中！','ja'=>'モジュール有効化をクリックすると、キーは暗号化されこのブラウザのLocalStorageにのみ保存されます！','ko'=>'모듈 활성화를 클릭하면 키가 암호화되어 이 브라우저의 LocalStorage에만 저장됩니다!','ar'=>'بمجرد النقر على تفعيل الوحدة، يتم تشفير مفاتيحك وتخزينها فقط في LocalStorage لهذا المتصفح!','hi'=>'मॉड्यूल सक्रिय करें पर क्लिक करने के बाद आपकी कुंजियाँ एन्क्रिप्ट होकर केवल इस ब्राउज़र के LocalStorage में संग्रहीत होती हैं!','pl'=>'Po kliknięciu AKTYWUJ MODUŁ klucze zostaną zaszyfrowane i zapisane TYLKO w LocalStorage TEJ przeglądarki!'),
        'The server never sees your 12 words. If you clear cookies or use a different device, you must re-import.' => array('tr'=>'Sunucu 12 kelimenizi asla görmez. Çerezleri temizlerseniz veya farklı bir cihaz kullanırsanız yeniden içe aktarmalısınız.','de'=>'Der Server sieht Ihre 12 Wörter nie. Bei Cookie-Löschung oder Gerätewechsel müssen Sie erneut importieren.','fr'=>'Le serveur ne voit jamais vos 12 mots. Si vous effacez les cookies ou changez d\'appareil, vous devez réimporter.','es'=>'El servidor nunca ve sus 12 palabras. Si borra cookies o usa otro dispositivo, debe reimportar.','pt'=>'O servidor nunca vê suas 12 palavras. Se limpar cookies ou usar outro dispositivo, deve reimportar.','it'=>'Il server non vede mai le tue 12 parole. Se cancelli i cookie o usi un altro dispositivo, devi reimportare.','nl'=>'De server ziet uw 12 woorden nooit. Bij het wissen van cookies of gebruik van een ander apparaat moet u opnieuw importeren.','ru'=>'Сервер никогда не видит ваши 12 слов. При очистке cookies или смене устройства необходим повторный импорт.','zh'=>'服务器永远不会看到您的12个单词。如果清除cookie或使用其他设备，必须重新导入。','ja'=>'サーバーは12単語を見ることはありません。Cookieを削除したり別のデバイスを使用する場合は再インポートが必要です。','ko'=>'서버는 12개의 단어를 볼 수 없습니다. 쿠키를 삭제하거나 다른 기기를 사용하면 다시 가져와야 합니다.','ar'=>'الخادم لا يرى كلماتك الـ 12 أبدًا. إذا مسحت ملفات تعريف الارتباط أو استخدمت جهازًا آخر، يجب إعادة الاستيراد.','hi'=>'सर्वर आपके 12 शब्दों को कभी नहीं देखता। यदि आप कुकीज़ साफ़ करते हैं या कोई अन्य डिवाइस उपयोग करते हैं, तो पुनः आयात करना होगा।','pl'=>'Serwer nigdy nie widzi twoich 12 słów. Po wyczyszczeniu cookies lub zmianie urządzenia musisz ponownie zaimportować.'),
        'Your keys are encrypted in this browser with AES-256-CBC. Commissions will be processed automatically from this device.' => array('tr'=>'Anahtarlarınız bu tarayıcıda AES-256-CBC ile şifrelenir. Komisyonlar bu cihazdan otomatik olarak işlenir.','de'=>'Ihre Schlüssel sind in diesem Browser mit AES-256-CBC verschlüsselt. Provisionen werden automatisch von diesem Gerät verarbeitet.','fr'=>'Vos clés sont chiffrées dans ce navigateur avec AES-256-CBC. Les commissions seront traitées automatiquement depuis cet appareil.','es'=>'Sus claves están cifradas en este navegador con AES-256-CBC. Las comisiones se procesarán automáticamente desde este dispositivo.','pt'=>'Suas chaves são criptografadas neste navegador com AES-256-CBC. As comissões serão processadas automaticamente deste dispositivo.','it'=>'Le tue chiavi sono crittografate in questo browser con AES-256-CBC. Le commissioni verranno elaborate automaticamente da questo dispositivo.','nl'=>'Uw sleutels zijn versleuteld in deze browser met AES-256-CBC. Commissies worden automatisch verwerkt vanaf dit apparaat.','ru'=>'Ваши ключи зашифрованы в этом браузере с помощью AES-256-CBC. Комиссии будут обрабатываться автоматически с этого устройства.','zh'=>'您的密钥在此浏览器中使用AES-256-CBC加密。佣金将从此设备自动处理。','ja'=>'AES-256-CBCでこのブラウザで暗号化されています。手数料はこのデバイスから自動的に処理されます。','ko'=>'키는 이 브라우저에서 AES-256-CBC로 암호화됩니다. 수수료는 이 기기에서 자동으로 처리됩니다.','ar'=>'مفاتيحك مشفرة في هذا المتصفح بـ AES-256-CBC. ستتم معالجة العمولات تلقائيًا من هذا الجهاز.','hi'=>'आपकी कुंजियाँ इस ब्राउज़र में AES-256-CBC से एन्क्रिप्ट हैं। कमीशन इस डिवाइस से स्वचालित रूप से संसाधित होंगे।','pl'=>'Twoje klucze są zaszyfrowane w tej przeglądarce za pomocą AES-256-CBC. Prowizje będą przetwarzane automatycznie z tego urządzenia.'),
        'This browser is NOT authorized to process commissions. Fee payments are bound to the device where the mnemonic was first entered.' => array('tr'=>'Bu tarayıcı komisyon işlemeye YETKİLİ DEĞİLDİR. Ücret ödemeleri, anımsatıcı kelimelerin ilk girildiği cihaza bağlıdır.','de'=>'Dieser Browser ist NICHT autorisiert, Provisionen zu verarbeiten. Gebührenzahlungen sind an das Gerät gebunden, auf dem die Mnemonik zuerst eingegeben wurde.','fr'=>'Ce navigateur n\'est PAS autorisé à traiter les commissions. Les paiements de frais sont liés à l\'appareil où le mnémonique a été saisi.','es'=>'Este navegador NO está autorizado para procesar comisiones. Los pagos de comisiones están vinculados al dispositivo donde se ingresó el mnemónico.','pt'=>'Este navegador NÃO está autorizado a processar comissões. Os pagamentos de taxas estão vinculados ao dispositivo onde o mnemônico foi inserido.','it'=>'Questo browser NON è autorizzato a elaborare commissioni. I pagamenti sono legati al dispositivo dove è stato inserito il mnemonico.','nl'=>'Deze browser is NIET geautoriseerd om commissies te verwerken. Betalingen zijn gebonden aan het apparaat waar de mnemonische zin is ingevoerd.','ru'=>'Этот браузер НЕ авторизован для обработки комиссий. Платежи привязаны к устройству, на котором была введена мнемоника.','zh'=>'此浏览器未被授权处理佣金。费用支付绑定到首次输入助记词的设备。','ja'=>'このブラウザは手数料処理の権限がありません。手数料支払いはニーモニックが最初に入力されたデバイスに紐付けられています。','ko'=>'이 브라우저는 수수료 처리 권한이 없습니다. 수수료 결제는 니모닉이 처음 입력된 기기에 연결되어 있습니다.','ar'=>'هذا المتصفح غير مصرح له بمعالجة العمولات. مدفوعات الرسوم مرتبطة بالجهاز الذي تم إدخال الكلمات المفتاحية فيه أولاً.','hi'=>'यह ब्राउज़र कमीशन प्रोसेस करने के लिए अधिकृत नहीं है। शुल्क भुगतान उस डिवाइस से जुड़े हैं जहाँ स्मरणीय शब्द पहली बार दर्ज किए गए थे।','pl'=>'Ta przeglądarka NIE jest autoryzowana do przetwarzania prowizji. Płatności są powiązane z urządzeniem, na którym wprowadzono mnemonik.'),
        'If you want to use THIS device for automatic payments, you MUST re-import your 12-word mnemonic in the "Import Existing Wallet" section.' => array('tr'=>'Bu cihazı otomatik ödemeler için kullanmak istiyorsanız, 12 kelimelik anımsatıcınızı "Mevcut Cüzdanı İçe Aktar" bölümünden yeniden içe aktarmalısınız.','de'=>'Wenn Sie DIESES Gerät für automatische Zahlungen verwenden möchten, MÜSSEN Sie Ihre 12-Wort-Mnemonik im Abschnitt "Vorhandenes Wallet importieren" erneut importieren.','fr'=>'Si vous souhaitez utiliser CET appareil pour les paiements automatiques, vous DEVEZ réimporter votre mnémonique de 12 mots dans la section "Importer un portefeuille existant".','es'=>'Si desea usar ESTE dispositivo para pagos automáticos, DEBE reimportar su mnemónico de 12 palabras en la sección "Importar billetera existente".','pt'=>'Se quiser usar ESTE dispositivo para pagamentos automáticos, DEVE reimportar seu mnemônico de 12 palavras na seção "Importar carteira existente".','it'=>'Se vuoi usare QUESTO dispositivo per i pagamenti automatici, DEVI reimportare il tuo mnemonico di 12 parole nella sezione "Importa portafoglio esistente".','nl'=>'Als u DIT apparaat wilt gebruiken voor automatische betalingen, MOET u uw 12-woordige mnemonische zin opnieuw importeren in het gedeelte "Bestaand portemonnee importeren".','ru'=>'Если вы хотите использовать ЭТО устройство для автоматических платежей, вы ДОЛЖНЫ повторно импортировать вашу 12-словную мнемонику в разделе "Импортировать существующий кошелёк".','zh'=>'如果您想使用此设备进行自动付款，必须在"导入现有钱包"部分重新导入您的12个助记词。','ja'=>'このデバイスで自動支払いを使用するには、「既存のウォレットをインポート」セクションで12単語のニーモニックを再インポートする必要があります。','ko'=>'이 기기에서 자동 결제를 사용하려면 "기존 지갑 가져오기" 섹션에서 12개의 니모닉 단어를 다시 가져와야 합니다.','ar'=>'إذا كنت تريد استخدام هذا الجهاز للمدفوعات التلقائية، يجب إعادة استيراد الكلمات المفتاحية الـ 12 في قسم "استيراد محفظة موجودة".','hi'=>'यदि आप इस डिवाइस को स्वचालित भुगतान के लिए उपयोग करना चाहते हैं, तो आपको "मौजूदा वॉलेट आयात करें" अनुभाग में अपने 12-शब्द के स्मरणीय शब्दों को पुनः आयात करना होगा।','pl'=>'Jeśli chcesz używać TEGO urządzenia do automatycznych płatności, MUSISZ ponownie zaimportować swój 12-wyrazowy mnemonik w sekcji "Importuj istniejący portfel".'),
        'Failure to settle commissions will eventually lead to the deactivation of your OmniXEP Payment Gateway.' => array('tr'=>'Komisyonların ödenmemesi sonunda OmniXEP Ödeme Ağ Geçidinizin devre dışı bırakılmasına yol açacaktır.','de'=>'Die Nichtbegleichung von Provisionen führt letztendlich zur Deaktivierung Ihres OmniXEP Payment Gateways.','fr'=>'Le non-règlement des commissions entraînera la désactivation de votre passerelle de paiement OmniXEP.','es'=>'No liquidar las comisiones eventualmente llevará a la desactivación de su pasarela de pago OmniXEP.','pt'=>'A falha em liquidar comissões levará à desativação do seu Gateway de Pagamento OmniXEP.','it'=>'Il mancato pagamento delle commissioni porterà alla disattivazione del tuo OmniXEP Payment Gateway.','nl'=>'Het niet afhandelen van commissies leidt uiteindelijk tot deactivering van uw OmniXEP Payment Gateway.','ru'=>'Неуплата комиссий приведёт к деактивации вашего платёжного шлюза OmniXEP.','zh'=>'未能结算佣金将最终导致您的OmniXEP支付网关被停用。','ja'=>'手数料の未払いは最終的にOmniXEP決済ゲートウェイの無効化につながります。','ko'=>'수수료를 정산하지 않으면 OmniXEP 결제 게이트웨이가 비활성화됩니다.','ar'=>'عدم تسوية العمولات سيؤدي في النهاية إلى تعطيل بوابة الدفع OmniXEP الخاصة بك.','hi'=>'कमीशन का भुगतान न करने पर अंततः आपके OmniXEP भुगतान गेटवे को निष्क्रिय कर दिया जाएगा।','pl'=>'Brak rozliczenia prowizji ostatecznie doprowadzi do dezaktywacji bramki płatności OmniXEP.'),
        'A 0.8% sales commission is collected automatically from this Fee Wallet (as XEP). Always maintain 10,000 XEP+ in the funding wallet to ensure uninterrupted merchant service.' => array('tr'=>'Bu Ücret Cüzdanından otomatik olarak %0.8 satış komisyonu tahsil edilir (XEP olarak). Kesintisiz satıcı hizmeti sağlamak için fonlama cüzdanında her zaman 10.000 XEP+ bulundurun.','de'=>'Eine 0,8% Verkaufsprovision wird automatisch aus diesem Gebühren-Wallet (als XEP) erhoben. Halten Sie immer 10.000 XEP+ im Funding-Wallet für unterbrechungsfreien Service.','fr'=>'Une commission de 0,8% est collectée automatiquement depuis ce portefeuille de frais (en XEP). Maintenez toujours 10 000 XEP+ pour un service continu.','es'=>'Se cobra automáticamente una comisión del 0,8% de esta billetera de comisiones (como XEP). Mantenga siempre 10.000 XEP+ para un servicio ininterrumpido.','pt'=>'Uma comissão de 0,8% é coletada automaticamente desta carteira de taxas (como XEP). Mantenha sempre 10.000 XEP+ para serviço ininterrupto.','it'=>'Una commissione dello 0,8% viene raccolta automaticamente da questo portafoglio commissioni (come XEP). Mantieni sempre 10.000 XEP+ per un servizio ininterrotto.','nl'=>'Een verkoopcommissie van 0,8% wordt automatisch geïnd uit deze kostenportemonnee (als XEP). Houd altijd 10.000 XEP+ aan voor ononderbroken service.','ru'=>'Комиссия 0,8% от продаж автоматически списывается из этого кошелька комиссий (в XEP). Всегда поддерживайте 10 000 XEP+ для бесперебойного обслуживания.','zh'=>'0.8%的销售佣金将从此手续费钱包中自动收取（以XEP计）。请始终保持10,000 XEP+以确保商户服务不中断。','ja'=>'0.8%の販売手数料がこの手数料ウォレットから自動的に徴収されます（XEP建て）。中断のないサービスのため常に10,000 XEP以上を維持してください。','ko'=>'0.8%의 판매 수수료가 이 수수료 지갑에서 자동으로 징수됩니다(XEP). 중단 없는 서비스를 위해 항상 10,000 XEP 이상을 유지하세요.','ar'=>'يتم تحصيل عمولة مبيعات بنسبة 0.8% تلقائيًا من محفظة الرسوم هذه (بـ XEP). حافظ دائمًا على 10,000 XEP+ لضمان خدمة مستمرة.','hi'=>'इस शुल्क वॉलेट से 0.8% बिक्री कमीशन स्वचालित रूप से एकत्र किया जाता है (XEP के रूप में)। निर्बाध सेवा के लिए हमेशा 10,000 XEP+ बनाए रखें।','pl'=>'Prowizja 0,8% od sprzedaży jest automatycznie pobierana z tego portfela opłat (jako XEP). Utrzymuj zawsze 10 000 XEP+ dla nieprzerwanej usługi.'),

        // Checkout - Customer Facing
        'SECURE PAYMENT SYSTEM' => array('tr'=>'GÜVENLİ ÖDEME SİSTEMİ','de'=>'SICHERES ZAHLUNGSSYSTEM','fr'=>'SYSTÈME DE PAIEMENT SÉCURISÉ','es'=>'SISTEMA DE PAGO SEGURO','pt'=>'SISTEMA DE PAGAMENTO SEGURO','it'=>'SISTEMA DI PAGAMENTO SICURO','nl'=>'VEILIG BETALINGSSYSTEEM','ru'=>'БЕЗОПАСНАЯ ПЛАТЁЖНАЯ СИСТЕМА','zh'=>'安全支付系统','ja'=>'セキュア決済システム','ko'=>'안전 결제 시스템','ar'=>'نظام دفع آمن','hi'=>'सुरक्षित भुगतान प्रणाली','pl'=>'BEZPIECZNY SYSTEM PŁATNOŚCI'),
        'Pay for your order securely, do not leave the screen until your order is created.' => array('tr'=>'Siparişinizi güvenle ödeyin, sipariş oluşturulana kadar ekrandan ayrılmayın.','de'=>'Bezahlen Sie sicher. Verlassen Sie den Bildschirm nicht, bis die Bestellung erstellt ist.','fr'=>'Payez votre commande en toute sécurité, ne quittez pas l\'écran.','es'=>'Pague su pedido de forma segura, no abandone la pantalla.','pt'=>'Pague com segurança, não saia da tela até o pedido ser criado.','it'=>'Paga in sicurezza, non lasciare lo schermo fino alla creazione dell\'ordine.','nl'=>'Betaal veilig, verlaat het scherm niet tot uw bestelling is aangemaakt.','ru'=>'Оплатите заказ безопасно, не покидайте страницу.','zh'=>'安全支付，订单创建前请勿离开页面。','ja'=>'安全に決済します。注文が作成されるまで画面を離れないでください。','ko'=>'안전하게 결제하세요. 주문이 생성될 때까지 화면을 떠나지 마세요.','ar'=>'ادفع بأمان، لا تغادر الشاشة حتى يتم إنشاء طلبك.','hi'=>'सुरक्षित रूप से भुगतान करें, ऑर्डर बनने तक स्क्रीन न छोड़ें।','pl'=>'Zapłać bezpiecznie, nie opuszczaj ekranu do utworzenia zamówienia.'),
        'Please wait until your order is created...' => array('tr'=>'Siparişiniz oluşturulana kadar lütfen bekleyin...','de'=>'Bitte warten Sie, bis Ihre Bestellung erstellt wird...','fr'=>'Veuillez patienter pendant la création de votre commande...','es'=>'Espere mientras se crea su pedido...','pt'=>'Aguarde enquanto seu pedido é criado...','it'=>'Attendere la creazione dell\'ordine...','nl'=>'Even geduld, uw bestelling wordt aangemaakt...','ru'=>'Пожалуйста, подождите, заказ создаётся...','zh'=>'请等待订单创建...','ja'=>'注文を作成しています。お待ちください...','ko'=>'주문이 생성될 때까지 기다려주세요...','ar'=>'يرجى الانتظار حتى يتم إنشاء طلبك...','hi'=>'कृपया प्रतीक्षा करें, आपका ऑर्डर बनाया जा रहा है...','pl'=>'Proszę czekać, zamówienie jest tworzone...'),
        'Exchange rate is fixed for 30 seconds. It will be updated when the time expires.' => array('tr'=>'Döviz kuru 30 saniye sabitlenir. Süre dolduğunda güncellenecektir.','de'=>'Der Wechselkurs ist 30 Sekunden gültig und wird dann aktualisiert.','fr'=>'Le taux de change est fixé pour 30 secondes puis sera mis à jour.','es'=>'El tipo de cambio se fija por 30 segundos y se actualizará al expirar.','pt'=>'A taxa de câmbio é fixada por 30 segundos e será atualizada ao expirar.','it'=>'Il tasso di cambio è fisso per 30 secondi e verrà aggiornato alla scadenza.','nl'=>'De wisselkoers is 30 seconden vast en wordt daarna bijgewerkt.','ru'=>'Курс зафиксирован на 30 секунд и будет обновлён после истечения.','zh'=>'汇率固定30秒，到期后将更新。','ja'=>'為替レートは30秒固定され、期限切れ時に更新されます。','ko'=>'환율은 30초간 고정되며, 만료 시 갱신됩니다.','ar'=>'سعر الصرف ثابت لمدة 30 ثانية وسيتم تحديثه عند انتهاء المدة.','hi'=>'विनिमय दर 30 सेकंड के लिए तय है। समय समाप्त होने पर अपडेट होगी।','pl'=>'Kurs wymiany jest stały przez 30 sekund i zostanie zaktualizowany po upływie czasu.'),
