/**
 * Translate a string based on current language
 */
function __omnixep($text) {
    $lang = omnixep_get_current_lang();
    if ($lang === 'en') return $text;
    
    $translations = omnixep_get_translations();
    if (isset($translations[$text][$lang])) {
        return $translations[$text][$lang];
    }
    return $text;
}

/**
 * AJAX handler for saving language preference
 */
add_action('wp_ajax_omnixep_set_language', 'omnixep_ajax_set_language');
function omnixep_ajax_set_language() {
    if (!current_user_can('manage_woocommerce')) {
        wp_send_json_error('Forbidden');
    }
    $lang = sanitize_text_field($_POST['lang'] ?? 'en');
    $languages = omnixep_get_languages();
    if (!isset($languages[$lang])) {
        wp_send_json_error('Invalid language');
    }
    update_option('omnixep_admin_language', $lang);
    wp_send_json_success(array('lang' => $lang));
}
